# owner: platform
import unittest

from hourglass.errors import OutsideHoursError, ProjectError
from hourglass.gaps import coverage_gaps
from hourglass.models import Span

OPENING = Span(540, 1020)

class GapTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            coverage_gaps([], OPENING), ["gap 09:00-17:00 (480 min)"]
        )

    def test_gap_between_two_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(coverage_gaps(worked, OPENING), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 720)]
        self.assertEqual(
            coverage_gaps(worked, OPENING),
            ["gap 09:00-10:00 (60 min)", "gap 12:00-17:00 (300 min)"]
        )

    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(coverage_gaps([Span(540, 1020)], OPENING), [])

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 720), Span(720, 1020)]
        self.assertEqual(coverage_gaps(worked, OPENING), [])

    def test_overlapping_spans_are_not_a_gap(self):
        worked = [Span(540, 800), Span(700, 1020)]
        self.assertEqual(coverage_gaps(worked, OPENING), [])

    def test_unordered_input(self):
        worked = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(coverage_gaps(worked, OPENING), ["gap 12:00-13:00 (60 min)"])

    def test_contained_span_does_not_hide_gap(self):
        worked = [Span(540, 1020), Span(600, 660)]
        self.assertEqual(coverage_gaps(worked, OPENING), [])

    def test_span_from_opening_edge_to_edge(self):
        worked = [Span(540, 600), Span(1000, 1020)]
        self.assertEqual(coverage_gaps(worked, OPENING), ["gap 10:00-16:40 (400 min)"])

class OutsideHoursTests(unittest.TestCase):
    def test_span_starting_before_opening(self):
        with self.assertRaises(OutsideHoursError):
            coverage_gaps([Span(500, 600)], OPENING)

    def test_span_ending_after_closing(self):
        with self.assertRaises(OutsideHoursError):
            coverage_gaps([Span(900, 1080)], OPENING)

    def test_error_is_a_project_error(self):
        with self.assertRaises(ProjectError):
            coverage_gaps([Span(1000, 1200)], OPENING)
